"""Generate standard OpenAPI types and route aliases; --check never changes files."""

import argparse
import json
import subprocess
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
CLIENT = ROOT / "onesa-ai-platform-frontend/packages/api-client"


def aliases() -> str:
    spec = json.loads((ROOT / "docs/api/openapi.json").read_text())
    lines = [
        "// Generated by scripts/generate_api_client.py; do not edit.",
        'import type { components, paths } from "./schema";',
    ]
    for name in sorted(spec["components"]["schemas"]):
        lines.append(f'export type {name} = components["schemas"][{json.dumps(name)}];')
    lines.append("export interface Operations {")
    for path, methods in sorted(spec["paths"].items()):
        if not path.startswith("/api/v1/"):
            continue
        for method, operation in sorted(methods.items()):
            if method not in {"get", "post", "patch", "delete", "put"}:
                continue
            route = f"paths[{json.dumps(path)}][{json.dumps(method)}]"
            body = (
                f'{route}["requestBody"]["content"]["application/json"]'
                if "application/json"
                in operation.get("requestBody", {}).get("content", {})
                else "undefined"
            )
            success = next(
                (
                    (code, value)
                    for code, value in operation["responses"].items()
                    if code.startswith("2")
                ),
                ("204", {}),
            )
            code, response = success
            result = (
                f'{route}["responses"][{code}]["content"]["application/json"]'
                if "application/json" in response.get("content", {})
                else "void"
            )
            key = method.upper() + " " + path.removeprefix("/api/v1")
            lines.append(
                f"  {json.dumps(key)}: {{ body: {body}; response: {result} }};"
            )
    lines.append("}")
    return "\n".join(lines) + "\n"


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    tool = ROOT / "scripts/contract-tools/node_modules/.bin/openapi-typescript"
    if not tool.exists():
        raise SystemExit("Run npm ci --prefix scripts/contract-tools first")
    with tempfile.TemporaryDirectory(prefix="onesa-contract-") as directory:
        generated = Path(directory) / "schema.d.ts"
        subprocess.run(
            [str(tool), str(ROOT / "docs/api/openapi.json"), "-o", str(generated)],
            check=True,
        )
        outputs = {
            CLIENT / "schema.d.ts": generated.read_text(),
            CLIENT / "contracts.ts": aliases(),
        }
        for path, content in outputs.items():
            if args.check:
                if not path.exists() or path.read_text() != content:
                    raise SystemExit("API client contract drift; run make api-client")
            else:
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(content)


if __name__ == "__main__":
    main()
